prts.feedbackvariables:
varsl:listofvars(expand(ans1));
bvars:sort(listify(setdifference(setify(varsl),setify([x,c1,c2]))));
an1:expand(ans1);

wvars:setify([X,t,T,x1,X1,x2,X2]);
wcona:setify([C1,k1,K1,A,a]);
wconb:setify([C2,k2,K2,B,b]);

for i:1 while i<=length(bvars) do (if elementp(bvars[i],wvars) then  an1:ev(an1,bvars[i]=x) else (if elementp(bvars[i],wcona) then  an1:ev(an1,bvars[i]=c1) else (if elementp(bvars[i],wconb) then  an1:ev(an1,bvars[i]=c2))));

stdivcheck:ev(diff(an1,x,2)-c1*diff(an1,x)+c2*an1,simp);
